import{createSelectedGameplayScenePreparer}from'../gohyeon-gameplay/prepare-recovery-scenes.mjs';
import{createS4DistanceGym4Scene as createGym4Scene}from'../gohyeon-gameplay/encounter/movement-proof.mjs';import{GYM4_WARPS}from'./fixed-warp-registration.mjs';
const near=(r,n)=>r.approach.rows.some(([y,lo,hi])=>n.foot[1]===y&&n.foot[0]>=lo&&n.foot[0]<hi);
export function createGym4JourneyScenePreparer({gym4Provider,...options}){const base=createSelectedGameplayScenePreparer(options);let gymEpoch=0;return async location=>{if(location.mapId==='world:gym:4')return createGym4Scene({location,registry:options.registry,provider:gym4Provider,sessionEpoch:++gymEpoch});const scene=await base(location);if(scene.mapId!=='world:hub:S4')return scene;const inspect=scene.inspect.bind(scene),hint=scene.proximityHint.bind(scene),row=GYM4_WARPS[0];scene.proximityHint=()=>{const n=scene.readNative();return n&&near(row,n)?'생활 체육관 · 위를 보고 조사':hint()};scene.inspect=async execution=>{const n=scene.readNative();if(n&&n.facing===row.facing&&near(row,n)){if(scene.disposed||scene.locked||scene.world!==options.getWorld()||scene.world?.busy||scene.world?.inputLocked)throw Error('INPUT_LOCKED');if(typeof execution!=='function')throw Error('TRUSTED_EXECUTION_REQUIRED');return execution(row.pointId)}return inspect(execution)};return scene}}
